import { forwardRef } from 'react';
import clsx from 'clsx';

export const Button = forwardRef(function Button(
  { variant = 'neutral', size = 'lg', block, loading, disabled,
    iconStart, iconEnd, children, className, ...rest }, ref) {
  return (
    <button
      ref={ref}
      className={clsx('t-btn', `t-btn--${variant}`, `t-btn--${size}`, block && 't-btn--block', className)}
      data-loading={loading || undefined}
      aria-busy={loading || undefined}
      disabled={disabled || loading}
      {...rest}
    >
      {iconStart}
      {children}
      {iconEnd}
    </button>
  );
});

export function IconButton({ variant = 'ghost', size = 'md', round, label, children, className, ...rest }) {
  return (
    <button
      className={clsx('t-icon-btn', variant !== 'ghost' && `t-icon-btn--${variant}`,
                      size === 'sm' && 't-icon-btn--sm', round && 't-icon-btn--round', className)}
      aria-label={label}
      {...rest}
    >{children}</button>
  );
}

export function BuyBoxButton({ variant = 'red', compact, ad, seller, price, ...rest }) {
  const label = [price, seller, ad && 'آگهی'].filter(Boolean).join('، ');
  return (
    <button
      className={clsx('t-buybox', variant === 'blue' && 't-buybox--offline', compact && 't-buybox--compact')}
      aria-label={label}
      {...rest}
    >
      <span className="t-buybox__body">
        <span className="t-buybox__seller">{seller}</span>
        {!compact && <span className="t-buybox__price">{price}</span>}
      </span>
      {ad && <span className="t-buybox__ad">آگهی</span>}
    </button>
  );
}

export function SplitButton({ variant = 'red', children, onAction, menuLabel, items = [] }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="t-btn-split">
      <button type="button" className={`t-btn t-btn--${variant}`} onClick={onAction}>
        {children}
      </button>
      <button
        type="button"
        className={`t-btn t-btn--${variant} t-btn-split__more`}
        aria-label={menuLabel}
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen(o => !o)}
      >
        <Icon name="chevron--down" size={20} />
      </button>
      {open && <Menu items={items} onClose={() => setOpen(false)} />}
    </div>
  );
}

export function FilterBar({ items, sticky = false, onChange }) {
  return (
    <div className={clsx('t-filter-bar', sticky && 't-filter-bar--sticky')}>
      {items.map(item =>
        item.type === 'divider'
          ? <span key={item.id} className="t-filter-bar__divider" aria-hidden="true" />
          : <FilterChip key={item.id} {...item} onChange={v => onChange(item.id, v)} />
      )}
    </div>
  );
}

import guarantee from '@torob/brand/torob-guarantee.svg';

export function BrandMark({ size = 'md', as = 'span', ...rest }) {
  const Tag = as === 'link' ? 'a' : 'span';
  return (
    <Tag className={clsx('t-brand', size !== 'md' && `t-brand--${size}`)} {...rest}>
      <TorobLogo aria-hidden="true" />
    </Tag>
  );
}

/* The mark carries the claim on its own, so it needs a name when it stands alone. */
export function GuaranteeMark({ size = 24, labelled = false }) {
  return (
    <span className="t-guarantee" style={{ '--_s': `${Math.max(size, 16)}px` }}>
      <img src={guarantee} alt={labelled ? '' : 'ضمانت ترب'} role={labelled ? undefined : 'img'} />
    </span>
  );
}

const MARK = { telegram: TelegramMark, whatsapp: WhatsappMark, bale: BaleMark };

export function SocialLink({ service, href, label, showLabel = true }) {
  const Mark = MARK[service];
  return (
    <a className="t-social" href={href} rel="noopener"
       aria-label={showLabel ? undefined : label}>
      <span className="t-social__mark"><Mark aria-hidden="true" /></span>
      {showLabel && label}
    </a>
  );
}

const FA = '۰۱۲۳۴۵۶۷۸۹';
export const toFa = n => String(n).replace(/\d/g, d => FA[+d]);
export const formatPrice = n => toFa(n.toLocaleString('en-US')).replace(/,/g, '٬');

export function PriceDisplay({ value, size = 'md', from, was, unavailable, unit = 'تومان' }) {
  if (unavailable) return <span className="t-price t-price--unavailable"><span className="t-price__value">ناموجود</span></span>;
  return (
    <span className={clsx('t-price', size !== 'md' && `t-price--${size}`)}>
      {from && <span className="t-price__from">از</span>}
      <span className="t-price__value">{formatPrice(value)}</span>
      <span className="t-price__unit">{unit}</span>
      {was != null && <s className="t-price__was">{formatPrice(was)}</s>}
    </span>
  );
}

export function Badge({ tone = 'neutral', size = 'md', onImage, dot, icon, children }) {
  return (
    <span className={clsx('t-badge', tone !== 'neutral' && `t-badge--${tone}`,
                          size === 'sm' && 't-badge--sm', onImage && 't-badge--on-image')}>
      {dot && <span className="t-badge__dot" />}
      {icon}
      {tone === 'guarantee' ? <span className="t-badge__label">{children}</span> : children}
    </span>
  );
}

export function ProductCard({ product, size = 'md', variant = 'default', tags = [] }) {
  if (variant === 'empty') return <div className="t-product-card t-product-card--empty" aria-hidden="true"><span className="t-product-card__cell"><ImageCopy20 className="t-icon" /></span></div>;
  if (variant === 'more') return (
    <a className="t-product-card t-product-card--more" href={product.href} aria-label={`${toFa(product.moreCount)} محصول دیگر`}>
      <span className="t-product-card__grid">
        {product.preview.slice(0, 3).map(src => <span key={src} className="t-product-card__cell"><img src={src} alt="" /></span>)}
        <span className="t-product-card__cell"><bdi dir="ltr">+{toFa(product.moreCount)}</bdi></span>
      </span>
    </a>
  );
  const sm = size === 'sm';
  return (
    <a className={clsx('t-product-card', sm && 't-product-card--sm')} href={product.href}>
      <ProductThumb src={product.image} alt={product.title} size={size} badges={product.ad && <Badge tone="ad">آگهی</Badge>} />
      <span className="t-product-card__title">{product.title}</span>
      {!sm && tags.length > 0 && <span className="t-product-card__tags">{tags.map(t => <span key={t} className="t-product-card__tag">{t}</span>)}</span>}
      {sm ? <PriceDisplay value={product.price} size="sm" /> : (
        <span className="t-product-card__buy">
          <PriceDisplay value={product.priceFrom} from />
          <span className="t-product-card__foot">
            <span className="t-product-card__meta">در {toFa(product.sellerCount)} فروشگاه</span>
            <span className="t-product-card__actions">
              <button aria-label="خبرم کن"><Notification16 className="t-icon" /></button>
              <button aria-label="علاقه‌مندی" aria-pressed={!!product.saved}><Favorite16 className="t-icon" /></button>
            </span>
          </span>
        </span>
      )}
    </a>
  );
}

export function ProductThumb({ src, alt, size = 'md', badges, action }) {
  return (
    <div className={clsx('t-thumb', size !== 'md' && `t-thumb--${size}`)}>
      {src && <img src={src} alt={alt} loading="lazy" />}
      {badges && <div className="t-thumb__badges">{badges}</div>}
      {action && <div className="t-thumb__action">{action}</div>}
    </div>
  );
}

export function StoreCard({ store, context = 'list', products = [], kalabarg = false }) {
  return (
    <article className={clsx('t-store-card', context === 'pdp' && 't-store-card--pdp')}>
      <div className="t-store-card__head">
        <div className="t-store-card__info">
          <a className="t-store-card__name" href={store.href}>{store.name}<ChevronLeft16 className="t-icon t-icon--directional" /></a>
          {context === 'pdp' && <PriceDisplay value={store.price} />}
          <span className="t-store-card__address">{store.address} . <span className="t-store-card__distance">{store.distance}</span></span>
        </div>
        <img className="t-store-card__photo" src={store.photo} alt="" />
      </div>
      <div className="t-store-card__chips">
        <Button size="xs" variant="filter"><StatusDot closed={!store.open} />{store.open ? 'باز' : 'بسته'} تا {store.until}</Button>
        <Button size="xs" variant="filter"><Information16 className="t-icon" />توضیحات</Button>
        <Button size="xs" variant="filter"><Report16 className="t-icon" />گزارش</Button>
        {kalabarg && <Badge tone="kalabarg">کالابرگ</Badge>}
      </div>
      {products.length > 0 && <div className="t-store-card__rail">{products.map(p => <ProductCard key={p.id} product={p} size="sm" />)}</div>}
      <div className="t-store-card__actions">
        <Button family="blue" icon={<SendAltFilled20 />}>ارتباط با فروشگاه</Button>
        <Button family="blue-ghost" icon={<LocationFilled20 />}>مسیریابی</Button>
      </div>
    </article>
  );
}

export function OfferCard({ offer }) {
  const buy = offer.type === 'online'
    ? <Button family="red" icon={<ShoppingCart20 />}>برو به سایت</Button>
    : <SplitButton family={offer.type === 'offline' ? 'blue' : 'red'} icon={<ShoppingCart20 />}
                   label={offer.type === 'offline' ? 'ارتباط با فروشگاه' : 'برو به سایت'} />;
  return (
    <article className="t-offer">
      <div className="t-offer__top">
        <div className="t-offer__head">
          <span className="t-offer__seller"><GuaranteeMark size={24} /><a className="t-offer__name" href={offer.store.href}>{offer.store.name}<ChevronLeft16 className="t-icon t-icon--directional" /></a></span>
          {offer.type === 'both' ? <RatingPill {...offer.rating} /> : <PriceDisplay value={offer.price} size="lg" />}
        </div>
        <p className="t-offer__note">{offer.warranty}</p>
        {offer.type !== 'online' && <p className="t-offer__address">{offer.store.address} . {offer.store.distance}</p>}
      </div>
      <div className="t-offer__row">
        <span className="t-offer__perks">{offer.perks}</span>
        <Button size="xs" variant="filter"><Report16 className="t-icon" />گزارش</Button>
      </div>
      <div className="t-offer__row">
        {buy}
        {offer.type === 'both' ? <PriceDisplay value={offer.price} size="xl" /> : <RatingPill {...offer.rating} />}
      </div>
    </article>
  );
}

export function MapPin({ variant = 'poi', selected = false, price, count, label, icon }) {
  if (variant === 'dot') return <span className="t-pin t-pin--dot" role="img" aria-label={label} />;
  if (variant === 'me') return <span className="t-pin t-pin--me" role="img" aria-label="موقعیت شما" />;
  if (variant === 'cluster') return <button className="t-cluster" aria-label={`${toFa(count)} فروشگاه در این ناحیه`}>{toFa(count)}</button>;
  if (variant === 'hero') return (
    <button className="t-pin t-pin--hero" aria-pressed="true" aria-label={label}>
      <span className="t-pin__drop"><span className="t-pin__face">{icon}</span></span>
      <span className="t-pin__spot" /><span className="t-pin__label">{label}</span>
    </button>
  );
  if (variant === 'price') return (
    <button className="t-pin t-pin--price" aria-pressed={selected} aria-label={`${label}، ${price} تومان`}>
      <span className="t-pin__pill">{icon}{price}</span>
      <span className="t-pin__tail" /><span className="t-pin__spot" /><span className="t-pin__label">{label}</span>
    </button>
  );
  return <button className="t-pin" aria-label={label}>{icon}</button>;
}

export function ListItem({ as: As = 'button', lead, trail, title, subtitle, ...rest }) {
  return (
    <As className="t-list-item" {...rest}>
      {lead && <span className="t-list-item__lead">{lead}</span>}
      <span className="t-list-item__body">
        <span className="t-list-item__title">{title}</span>
        {subtitle && <span className="t-list-item__sub">{subtitle}</span>}
      </span>
      {trail && <span className="t-list-item__trail">{trail}</span>}
    </As>
  );
}

export function DataTable({ columns, rows, density = 'comfortable', freezeFirst, sort, onSort }) {
  return (
    <div className="t-table-wrap" tabIndex={0} role="region" aria-label="جدول داده">
      <table className={clsx('t-table', freezeFirst && 't-table--freeze', density === 'compact' && 't-table--compact')}>
        <thead>
          <tr>{columns.map(c => (
            <th key={c.key} scope="col" className={clsx(c.numeric && 't-num')}
                aria-sort={c.sortable ? (sort?.key === c.key ? sort.direction : 'none') : undefined}>
              {/* aria-sort belongs to the column header, not to the button inside it */}
              {c.sortable
                ? <button className="t-table__sort" onClick={() => onSort(c.key)}>
                    {c.label}<SortIcon />
                  </button>
                : c.label}
            </th>))}
          </tr>
        </thead>
        <tbody>{rows.map(r => (
          <tr key={r.id} aria-selected={r.selected || undefined}>
            {columns.map(c => <td key={c.key} className={clsx(c.numeric && 't-num')}>{c.render(r)}</td>)}
          </tr>))}
        </tbody>
      </table>
    </div>
  );
}

export function StatCard({ label, value, delta }) {
  const DIR = { up: 'افزایش', down: 'کاهش', flat: 'بدون تغییر' };
  return (
    <div className="t-stat">
      <div className="t-stat__label">{label}</div>
      <div className="t-stat__value">{value}</div>
      {delta && (
        <div className={clsx('t-stat__delta', `t-stat__delta--${delta.direction}`)}>
          <span aria-hidden="true">{delta.direction === 'up' ? '▲' : delta.direction === 'down' ? '▼' : ''}</span>
          <span className="t-visually-hidden">{DIR[delta.direction]}</span>
          {delta.value} {delta.period}
        </div>
      )}
    </div>
  );
}

/* Jalali conversion belongs in a library, not in the component.
   The component's job is the interaction and the accessible names. */
import { toJalali, jalaliMonthName, jalaliDaysInMonth } from '@torob/date';

export function DateField({ value, onChange, range, presets = true }) {
  const [y, mo] = value.split('/').map(Number);
  const days = jalaliDaysInMonth(y, mo);
  return (
    <div className="t-cal__grid" role="grid" aria-label={`${jalaliMonthName(mo)} ${toFa(y)}`}>
      {/* شنبه first — the Iranian week does not start on Sunday.
          Every cell sits inside a row: a grid without rows is not a grid. */}
      <div className="t-cal__row" role="row">
        {['ش','ی','د','س','چ','پ','ج'].map((d, i) => (
          <div key={d} className="t-cal__dow" role="columnheader" data-weekend={i >= 5 || undefined}>{d}</div>
        ))}
      </div>
      {weeksOf(y, mo, days).map((week, r) => (
        <div key={r} className="t-cal__row" role="row">
          {week.map(day => day === null ? <div key={`e${r}`} /> : (
            <button key={day} className="t-cal__day" role="gridcell"
                    aria-selected={day === Number(value.split('/')[2])}
                    aria-label={`${toFa(day)} ${jalaliMonthName(mo)} ${toFa(y)}`}
                    onClick={() => onChange(`${y}/${mo}/${day}`)}>
              {toFa(day)}
            </button>
          ))}
        </div>
      ))}
    </div>
  );
}

export function AppShell({ nav, current, collapsed, children, topbar, brand }) {
  return (
    <div className="t-shell" data-nav={collapsed ? 'collapsed' : undefined}>
      <div className="t-shell__brand">{brand}</div>
      <div className="t-shell__top">{topbar}</div>
      <nav className="t-shell__nav" aria-label="ناوبری پنل">
        {nav.map(g => (
          <Fragment key={g.title}>
            {g.title && <div className="t-navgroup__title">{g.title}</div>}
            {g.items.map(i => (
              <a key={i.href} href={i.href} className="t-navitem"
                 aria-label={collapsed ? i.label : undefined}
                 aria-current={i.href === current ? 'page' : undefined}>
                {i.icon}{!collapsed && i.label}
                {i.count != null && !collapsed && <span className="t-navitem__count">{toFa(i.count)}</span>}
              </a>
            ))}
          </Fragment>
        ))}
      </nav>
      <main className="t-shell__main" id="main">{children}</main>
    </div>
  );
}

export function DescriptionList({ items }) {
  return (
    <dl className="t-dl">
      {items.map(i => (
        <Fragment key={i.label}>
          <dt>{i.label}</dt>
          <dd className={clsx(i.numeric && 't-num-tabular')}>{i.value ?? '—'}</dd>
        </Fragment>
      ))}
    </dl>
  );
}

const ToastContext = createContext(null);
export const useToast = () => useContext(ToastContext);

export function ToastProvider({ children }) {
  const [items, setItems] = useState([]);
  const show = useCallback(t => {
    const id = crypto.randomUUID();
    setItems(x => [...x.slice(-2), { ...t, id }]);          // never more than three
    const ms = t.duration ?? (t.action ? 8000 : 4200);       // actions need reachable time
    if (ms) setTimeout(() => setItems(x => x.filter(i => i.id !== id)), ms);
  }, []);
  return (
    <ToastContext.Provider value={{ show }}>
      {children}
      <div className="t-toast-region" role="status" aria-live="polite">
        {items.map(t => (
          <div key={t.id} className={clsx('t-toast', t.tone && `t-toast--${t.tone}`)}
               role={t.tone === 'critical' ? 'alert' : undefined}>
            <div className="t-toast__body">
              <div className="t-toast__title">{t.title}</div>
              {t.desc && <div className="t-toast__desc">{t.desc}</div>}
            </div>
            {t.action && <button className="t-toast__action" onClick={t.action.onClick}>{t.action.label}</button>}
            <button className="t-toast__close" aria-label="بستن"
                    onClick={() => setItems(x => x.filter(i => i.id !== t.id))}>✕</button>
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
}

export function Alert({ tone = 'info', title, actions, onDismiss, children }) {
  return (
    <div className={clsx('t-alert', `t-alert--${tone}`)} role={tone === 'critical' ? 'alert' : 'status'}>
      <span className="t-alert__icon" aria-hidden="true">{TONE_ICON[tone]}</span>
      <div className="t-alert__body">
        {title && <div className="t-alert__title">{title}</div>}
        <div>{children}</div>
        {actions && <div className="t-alert__actions">{actions}</div>}
      </div>
      {onDismiss && <IconButton size="sm" label="بستن" onClick={onDismiss}><CloseIcon /></IconButton>}
    </div>
  );
}

export function EmptyState({ variant = 'empty', inline, art, title, desc, action, code }) {
  return (
    <div className={clsx('t-empty', variant === 'error' && 't-empty--error', inline && 't-empty--inline')}>
      {art && <div className="t-empty__art" aria-hidden="true">{art}</div>}
      <div className="t-empty__title">{title}</div>
      {desc && <div className="t-empty__desc">{desc}</div>}
      {action && <div className="t-empty__actions">{action}</div>}
      {code && <div className="t-empty__code">{code}</div>}
    </div>
  );
}

export function Skeleton({ variant = 'block', width, height, className }) {
  return <div className={clsx('t-skeleton', variant !== 'block' && `t-skeleton--${variant}`, className)}
              style={{ inlineSize: width, blockSize: height }} aria-hidden="true" />;
}

export function Spinner({ size = 'md', label = 'در حال بارگذاری' }) {
  return (
    <span role="status">
      <span className={clsx('t-spinner', size !== 'md' && `t-spinner--${size}`)} />
      <span className="t-visually-hidden">{label}</span>
    </span>
  );
}

export function SearchField({ state = 'default', value, onChange, onClear, onVoice, onCamera, ...rest }) {
  const idle = state === 'default';
  return (
    <div className="t-search" data-state={state} role="search">
      <div className="t-input">
        {idle && <Search16 className="t-input__icon t-icon" />}
        <input className="t-input__el" type="search" value={value} onChange={onChange} aria-label="جستجو" {...rest} />
        <span className="t-search__actions">
          {idle ? <>
            <button className="t-search__tool" aria-label="جستجوی صوتی" onClick={onVoice}><Microphone20 className="t-icon" /></button>
            <button className="t-search__tool" aria-label="جستجو با تصویر" onClick={onCamera}><Camera16 className="t-icon" /></button>
          </> : <button className="t-search__clear" aria-label="پاک کردن جستجو" onClick={onClear}><Close20 className="t-icon" /></button>}
        </span>
      </div>
    </div>
  );
}

export function TextField({ label, hint, error, required, size = 'lg', id, ...rest }) {
  const uid = useId(), fid = id ?? uid, msgId = fid + '-msg';
  return (
    <div className="t-field">
      <label className="t-field__label" htmlFor={fid}>{label}{required && <span className="t-field__req">*</span>}</label>
      <div className={clsx('t-input', size !== 'lg' && `t-input--${size}`)} data-invalid={!!error || undefined}>
        <input className="t-input__el" id={fid} aria-invalid={!!error || undefined}
               aria-describedby={(error || hint) ? msgId : undefined} aria-required={required} {...rest} />
      </div>
      {error ? <span className="t-field__error" id={msgId}><WarningIcon />{error}</span>
             : hint && <span className="t-field__hint" id={msgId}>{hint}</span>}
    </div>
  );
}

export function SegmentedControl({ options, value, onChange, label, block = false }) {
  const move = (e, i) => {
    const d = { ArrowLeft: 1, ArrowRight: -1 }[e.key];   /* RTL: left is "next" */
    if (!d) return;
    e.preventDefault();
    const n = options[(i + d + options.length) % options.length];
    onChange(n.value);
  };
  return (
    <div className={clsx('t-segmented', block && 't-segmented--block')} role="radiogroup" aria-label={label}>
      {options.map((o, i) => (
        <button key={o.value} className="t-segmented__item" role="radio"
                aria-checked={o.value === value} tabIndex={o.value === value ? 0 : -1}
                onClick={() => onChange(o.value)} onKeyDown={e => move(e, i)}>
          {o.label}
        </button>
      ))}
    </div>
  );
}

export function Switch({ checked, onChange, label, disabled }) {
  return (
    <label className="t-switch">
      <input type="checkbox" checked={checked} disabled={disabled}
             onChange={e => onChange(e.target.checked)} />
      <span className="t-switch__track"><span className="t-switch__thumb" /></span>
      <span className="t-body-md">{label}</span>
    </label>
  );
}

export function RangeSlider({ min, max, value, onChange, step = 1, format = String }) {
  const pct = v => ((v - min) / (max - min)) * 100;
  return (
    <div className="t-range">
      <div className="t-range__values"><span>{format(value[0])}</span><span>{format(value[1])}</span></div>
      <div className="t-range__track">
        <div className="t-range__fill" style={{ insetInlineStart: pct(value[0]) + '%', inlineSize: (pct(value[1]) - pct(value[0])) + '%' }} />
        {value.map((v, i) => (
          <div key={i} className="t-range__thumb" role="slider" aria-label="بیشترین قیمت" tabIndex={0}
               style={{ insetInlineStart: pct(v) + '%' }}
               aria-valuemin={min} aria-valuemax={max} aria-valuenow={v} aria-valuetext={format(v)}
               onKeyDown={e => handleKey(e, i, v, { min, max, step, value, onChange })} />
        ))}
      </div>
    </div>
  );
}

export function Checkbox({ variant = 'checkbox', checked, onChange, label, ...rest }) {
  return (
    <label className={clsx('t-check', variant === 'radio' && 't-check--radio')}>
      <input type={variant} checked={checked} onChange={e => onChange(e.target.checked)} {...rest} />
      <span className="t-check__box">{variant === 'checkbox' && <CheckMark className="t-check__mark" />}</span>
      <span className="t-body-md">{label}</span>
    </label>
  );
}

export function QuantityStepper({ value, onChange, min = 1, max = 99 }) {
  return (
    <div className="t-stepper">
      <button className="t-stepper__btn" aria-label="کاهش تعداد"
              disabled={value <= min} onClick={() => onChange(value - 1)}><MinusIcon /></button>
      <span className="t-stepper__value" aria-live="polite">{toFa(value)}</span>
      <button className="t-stepper__btn" aria-label="افزایش تعداد"
              disabled={value >= max} onClick={() => onChange(value + 1)}><PlusIcon /></button>
    </div>
  );
}

export function ChoiceChips({ options, value, onChange, onClear, label }) {
  return (
    <div className="t-chip-group" role="group" aria-label={label}>
      {options.map(o => {
        const on = o.value === value;
        return (
          <span key={o.value} className="t-choice">
            <button className="t-choice__action" aria-pressed={on} onClick={() => onChange(o.value)}>
              {o.icon}{o.label}
            </button>
            {on && onClear && (
              <button className="t-choice__clear" aria-label={`حذف ${o.label}`}
                      onClick={onClear}><Close16 className="t-icon" /></button>
            )}
          </span>
        );
      })}
    </div>
  );
}

export function FilterChip({ active, count, opens, icon, children, ...rest }) {
  return (
    <button className="t-chip"
            {...(opens ? { 'aria-expanded': !!active, 'aria-haspopup': 'dialog' } : { 'aria-pressed': !!active })}
            {...rest}>
      {icon}{children}
      {count != null && <span className="t-chip__count">{toFa(count)}</span>}
      {opens && <ChevronDown16 className="t-icon t-chip__chevron" />}
    </button>
  );
}

export function Tabs({ options, value, onChange, label }) {
  return (
    <div className="t-tabs" role="tablist" aria-label={label}>
      {options.map(o => (
        <button key={o.value} className="t-tab" role="tab" id={`tab-${o.value}`}
                aria-selected={o.value === value} aria-controls={`panel-${o.value}`}
                tabIndex={o.value === value ? 0 : -1} onClick={() => onChange(o.value)}>
          {o.label}{o.count != null && <span className="t-tab__count">{toFa(o.count)}</span>}
        </button>
      ))}
    </div>
  );
}

export function PageHeader({ title, subtitle, onBack, actions }) {
  return (
    <header className="t-page-header">
      {onBack && <IconButton size="sm" label="بازگشت" onClick={onBack}><ChevronStart className="t-icon--directional" /></IconButton>}
      <div className="t-page-header__title">
        {title}
        {subtitle && <div className="t-page-header__sub">{subtitle}</div>}
      </div>
      {actions}
    </header>
  );
}

export function BottomNav({ items, current, label = 'ناوبری اصلی' }) {
  return (
    <nav className="t-bottom-nav" aria-label={label}>
      {items.map(i => (
        <a key={i.href} href={i.href} className="t-bottom-nav__item"
           aria-current={i.href === current ? 'page' : undefined}>
          {i.icon}{i.label}
        </a>
      ))}
    </nav>
  );
}

export function Breadcrumb({ items }) {
  return (
    <nav className="t-breadcrumb" aria-label="مسیر">
      <ol style={{ display: 'contents' }}>
        {items.map((it, i) => {
          const last = i === items.length - 1;
          return (
            <li key={it.href} style={{ display: 'contents' }}>
              {last ? <span className="t-breadcrumb__item" aria-current="page">{it.label}</span>
                    : <><a className="t-breadcrumb__item" href={it.href}>{it.label}</a>
                        <span className="t-breadcrumb__sep" aria-hidden="true">›</span></>}
            </li>
          );
        })}
      </ol>
    </nav>
  );
}

export function BottomSheet({ open, onClose, title, adaptive = true, children, footer }) {
  const ref = useRef(null);
  useFocusTrap(ref, open);
  useLockBodyScroll(open);
  useEffect(() => {
    if (!open) return;
    const onKey = e => e.key === 'Escape' && onClose();
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [open, onClose]);
  if (!open) return null;
  return createPortal(
    <>
      <div className="t-scrim" onClick={onClose} />
      <div className={clsx('t-sheet', adaptive && 't-sheet--adaptive')} ref={ref}
           role="dialog" aria-modal="true" aria-labelledby="sheet-title">
        <div className="t-sheet__grip" />
        <div className="t-sheet__head">
          <span className="t-sheet__title" id="sheet-title">{title}</span>
          <IconButton size="sm" label="بستن" onClick={onClose}><CloseIcon /></IconButton>
        </div>
        <div className="t-sheet__body">{children}</div>
        {footer && <div className="t-sheet__foot">{footer}</div>}
      </div>
    </>, document.body);
}

export function Modal({ open, onClose, title, children, footer }) {
  const ref = useRef(null);
  useFocusTrap(ref, open);
  useLockBodyScroll(open);
  if (!open) return null;
  return createPortal(
    <>
      <div className="t-scrim" onClick={onClose} />
      <div className="t-modal" ref={ref} role="dialog" aria-modal="true" aria-labelledby="modal-title">
        <div className="t-modal__head">
          <span className="t-modal__title" id="modal-title">{title}</span>
        </div>
        <div className="t-modal__body">{children}</div>
        {footer && <div className="t-modal__foot">{footer}</div>}
      </div>
    </>, document.body);
}

export function Accordion({ items, multiple, defaultOpen = [] }) {
  const [open, setOpen] = useState(new Set(defaultOpen));
  const toggle = id => setOpen(prev => {
    const next = new Set(multiple ? prev : []);
    prev.has(id) ? next.delete(id) : next.add(id);
    return next;
  });
  return (
    <div className="t-accordion">
      {items.map(it => (
        <div className="t-accordion__item" key={it.id}>
          <button className="t-accordion__trigger" aria-expanded={open.has(it.id)}
                  aria-controls={`panel-${it.id}`} id={`trigger-${it.id}`}
                  onClick={() => toggle(it.id)}>
            <span className="t-accordion__label">{it.label}</span>
            <ChevronDown className="t-accordion__chevron" />
          </button>
          <div className="t-accordion__panel" id={`panel-${it.id}`}
               aria-labelledby={`trigger-${it.id}`} hidden={!open.has(it.id)}>
            {it.content}
          </div>
        </div>
      ))}
    </div>
  );
}

export function Menu({ trigger, items, align = 'start' }) {
  const [open, setOpen] = useState(false);
  const isPhone = useMediaQuery('(max-width: 767px)');
  if (isPhone) return <><span onClick={() => setOpen(true)}>{trigger}</span>
    <BottomSheet open={open} onClose={() => setOpen(false)} title="عملیات">
      {items.map(i => <ListItem key={i.label} title={i.label} lead={i.icon} onClick={i.onSelect} />)}
    </BottomSheet></>;
  return (
    <Popover open={open} onOpenChange={setOpen} trigger={trigger} align={align}>
      <div className="t-popover" role="menu">
        {items.map(i => i.separator
          ? <div key={i.key} className="t-menu-sep" role="separator" />
          : <button key={i.label} role="menuitem" onClick={i.onSelect}
                    className={clsx('t-menu-item', i.tone === 'critical' && 't-menu-item--critical')}>
              {i.icon}{i.label}
            </button>)}
      </div>
    </Popover>
  );
}
